# One path, cohort 5, reference s = 0: the HonestDiD model through cohort_input().
one_path_fit <- function(beta = c(0.0150, -0.0050, 0.0100, 0.0550, 0.0750, 0.0640), scale = 1) {
  Sigma <- scale * (0.02^2 * 0.5^abs(outer(1:6, 1:6, "-")) + 0.01^2)     # s = -3, -2, -1, 1, 2, 3
  s <- c(-3:0, 1:3); nm <- paste0("c", seq_along(s)); ref <- which(s == 0L)
  b <- numeric(7L); b[-ref] <- beta; names(b) <- nm
  V <- matrix(0, 7L, 7L, dimnames = list(nm, nm)); V[-ref, -ref] <- Sigma
  info <- data.frame(coordinate = nm, cohort = 5L, relative_period = s, type = ifelse(s <= 0L, "pre", "post"))
  W <- diag(7L); dimnames(W) <- list(nm, nm)
  N <- matrix(0, 1L, 7L, dimnames = list(NULL, nm)); N[1L, ref] <- 1
  cohort_input(b, V, info, W, N, cohort_sizes = c("5" = 1), estimator = "cs_nt")
}

# Pre coefficients that fall to period 0, with almost no sampling noise: under a positive
# sign the restriction fails at every candidate value.
violated_fit <- function() one_path_fit(c(0.03, 0.02, 0.01, 0.055, 0.075, 0.064), scale = 1e-6)

quick_control <- list(lf.sims = 64L, grid.points = 21L, max.evaluations = 5000L)

# Two cohorts with different histories, for the rows.
cell <- function(g, s) paste0("delta_", if (s <= 0L) "pre" else "post", "_g", g, "_s", s)
two_path_names <- c(vapply(-2:2, cell, "", g = 3L), vapply(-3:3, cell, "", g = 5L))
two_path_info <- function() .hc_backend()$v3_parse_coordinates(two_path_names)
expected_row <- function(weights) {
  row <- stats::setNames(numeric(length(two_path_names)), two_path_names)
  row[names(weights)] <- weights
  row
}
difference <- function(plus, minus) expected_row(stats::setNames(c(1, -1), c(plus, minus)))
row_text <- function(A) sort(unname(apply(A, 1L, paste, collapse = " ")))

test_that("the nine restriction names map to their base and shape", {
  table <- list(SD = c("SD", "none"), SDB = c("SD", "sign"), SDM = c("SD", "monotone"),
                RM = c("RM", "none"), RMB = c("RM", "sign"), RMM = c("RM", "monotone"),
                SDRM = c("SDRM", "none"), SDRMB = c("SDRM", "sign"), SDRMM = c("SDRM", "monotone"))
  expect_setequal(.hc_restrictions, names(table))
  for (name in names(table)) {
    spec <- .hc_restriction_spec(name, "up")
    expect_identical(c(spec$base, spec$shape), table[[name]], info = name)
    expect_identical(spec$restriction, name)
    expect_identical(spec$direction, "up")
  }
})

test_that("restriction names match exactly and in any case", {
  fit <- one_path_fit()
  expect_error(cohort_sensitivity(fit, "S", M = 0), "should be one of")
  expect_error(cohort_sensitivity(fit, "R", M = 0), "should be one of")
  expect_error(cohort_sensitivity(fit, "SDRMX", M = 0), "should be one of")
  x <- cohort_sensitivity(fit, "sdrmb", M = 0, direction = "negative", seed = 1, control = quick_control)
  expect_identical(x$settings$restriction, "SDRMB")
})

test_that("FLCI stops under the seven restrictions, before the direction is checked", {
  fit <- one_path_fit()
  for (restriction in setdiff(.hc_restrictions, "SD")) {
    expect_error(cohort_sensitivity(fit, restriction, M = 0, method = "FLCI"),
                 "FLCI is available only under SD.", fixed = TRUE)
  }
  expect_error(cohort_sensitivity(fit, "SDB", M = 0, method = "FLCI", direction = "wrong", full.path = TRUE),
               "FLCI is available only under SD.", fixed = TRUE)
  rep <- .hc_representation(fit, .hc_targets(fit, "att")[[1L]]$target, "cohort")
  ans <- .hc_infer_one(rep, "SDB", 0, "flci", TRUE, 0.05, seed = 1, direction = "positive")
  expect_identical(ans$status, "inference_error")
  expect_identical(ans$message, "FLCI is available for SD, not SDB.")
})

test_that("B and M restrictions need their own direction, one string, exact case", {
  fit <- one_path_fit()
  for (restriction in c("SDB", "RMB", "SDRMB")) {
    message <- paste0(restriction, " requires direction = 'positive' or 'negative'.")
    for (direction in list(NULL, "increasing", "Positive", c("positive", "negative"), NA_character_, 1)) {
      expect_error(cohort_sensitivity(fit, restriction, M = 0, direction = direction), message, fixed = TRUE)
    }
  }
  for (restriction in c("SDM", "RMM", "SDRMM")) {
    message <- paste0(restriction, " requires direction = 'increasing' or 'decreasing'.")
    for (direction in list(NULL, "positive", "Increasing", c("increasing", "decreasing"), NA_character_, TRUE)) {
      expect_error(cohort_sensitivity(fit, restriction, M = 0, direction = direction), message, fixed = TRUE)
    }
  }
})

test_that("the other three restrictions refuse a direction", {
  fit <- one_path_fit()
  message <- paste0("direction applies only to SDB, RMB, and SDRMB (positive or negative) ",
                    "and to SDM, RMM, and SDRMM (increasing or decreasing).")
  for (restriction in c("SD", "RM", "SDRM")) {
    expect_error(cohort_sensitivity(fit, restriction, M = 0, direction = "positive"), message, fixed = TRUE)
  }
})

test_that("full.path is offered for SD, SDB, and SDM only, after the direction check", {
  fit <- one_path_fit()
  message <- "full.path applies only to SD, SDB, and SDM."
  expect_error(cohort_sensitivity(fit, "RM", M = 0, full.path = FALSE), message, fixed = TRUE)
  expect_error(cohort_sensitivity(fit, "SDRM", M = 0, full.path = TRUE), message, fixed = TRUE)
  expect_error(cohort_sensitivity(fit, "RMB", M = 0, direction = "positive", full.path = TRUE), message, fixed = TRUE)
  expect_error(cohort_sensitivity(fit, "SDRMM", M = 0, direction = "increasing", full.path = TRUE), message, fixed = TRUE)
  expect_error(cohort_sensitivity(fit, "RMB", M = 0, full.path = TRUE), "RMB requires direction", fixed = TRUE)
  expect_error(cohort_sensitivity(fit, "SDB", M = 0, direction = "positive", full.path = NA),
               "full.path must be TRUE or FALSE.", fixed = TRUE)
})

test_that("sign rows compare every post period with period 0 of the same cohort", {
  info <- two_path_info()
  positive <- .hc_backend()$v3_shape_rows(info, list(shape = "sign", direction = "positive"))
  periods <- list(c(3L, 1L), c(3L, 2L), c(5L, 1L), c(5L, 2L), c(5L, 3L))
  expected <- do.call(rbind, lapply(periods, function(p) difference(cell(p[1L], 0L), cell(p[1L], p[2L]))))
  expect_identical(rownames(positive), vapply(periods, function(p) paste0("sign_", cell(p[1L], p[2L])), ""))
  expect_identical(colnames(positive), two_path_names)
  expect_equal(unname(positive), unname(expected))
  negative <- .hc_backend()$v3_shape_rows(info, list(shape = "sign", direction = "negative"))
  expect_equal(unname(negative), -unname(expected))
  expect_identical(rownames(negative), rownames(positive))
})

test_that("monotonicity rows start at period 0, and a full path adds the pure pre steps", {
  info <- two_path_info()
  engine <- .hc_backend()
  increasing <- engine$v3_shape_rows(info, list(shape = "monotone", direction = "increasing"))
  steps <- list(c(3L, 1L), c(3L, 2L), c(5L, 1L), c(5L, 2L), c(5L, 3L))
  step_rows <- function(steps) do.call(rbind, lapply(steps, function(p)
    difference(cell(p[1L], p[2L] - 1L), cell(p[1L], p[2L]))))
  expect_equal(unname(increasing), unname(step_rows(steps)))
  decreasing <- engine$v3_shape_rows(info, list(shape = "monotone", direction = "decreasing"))
  expect_equal(unname(decreasing), -unname(step_rows(steps)))
  full <- engine$v3_shape_rows(info, list(shape = "monotone", direction = "increasing"), full_path = TRUE)
  pre <- list(c(3L, -1L), c(3L, 0L), c(5L, -2L), c(5L, -1L), c(5L, 0L))
  expect_equal(row_text(full), row_text(rbind(step_rows(steps), step_rows(pre))))
  window <- engine$v3_shape_rows(info, list(shape = "monotone", direction = "increasing"),
                                 pre_window = -2L, full_path = TRUE)
  expect_equal(row_text(window), row_text(rbind(step_rows(steps), step_rows(pre[-3L]))))
  expect_null(engine$v3_shape_rows(info, NULL))
  expect_null(engine$v3_shape_rows(info, list(shape = "none")))
})

test_that("full.path brings the pure pre steps of SDM into the moments", {
  # The fixture's pre path falls and then rises, so increasing steps fail before treatment.
  # M = 0.1 exceeds its pre-period second differences, 0.035 and 0.025 in size, so only the steps bind.
  fit <- one_path_fit()
  run <- function(full.path) cohort_sensitivity(fit, "SDM", M = 0.1, direction = "increasing",
                                                full.path = full.path, seed = 1, control = quick_control)
  expect_true(is.finite(run(FALSE)$intervals$plugin.lower[1L]))
  expect_true(is.na(run(TRUE)$intervals$plugin.lower[1L]))
})

test_that("every extra row sums to zero within a cohort", {
  info <- two_path_info()
  specs <- list(list(shape = "sign", direction = "positive"), list(shape = "sign", direction = "negative"),
                list(shape = "monotone", direction = "increasing"), list(shape = "monotone", direction = "decreasing"))
  for (spec in specs) {
    rows <- .hc_backend()$v3_shape_rows(info, spec, full_path = TRUE)
    for (g in c(3L, 5L)) expect_equal(unname(rowSums(rows[, info$cohort == g])), rep(0, nrow(rows)))
  }
})

test_that("the attached rows follow the SD rows and do not change them", {
  engine <- .hc_backend()
  info <- two_path_info()
  sd <- engine$v3_sd_restriction(info, 0.1)
  built <- list(representation = list(coordinate_info = info), restriction = sd)
  expect_identical(engine$v3_attach_shape(built, NULL), built)
  expect_identical(engine$v3_attach_shape(built, list(shape = "none")), built)
  shaped <- engine$v3_attach_shape(built, list(shape = "monotone", direction = "decreasing"), full_path = TRUE)
  rows <- engine$v3_shape_rows(info, list(shape = "monotone", direction = "decreasing"), full_path = TRUE)
  n <- nrow(sd$A_Delta)
  expect_identical(shaped$restriction$A_Delta[seq_len(n), , drop = FALSE], sd$A_Delta)
  expect_identical(shaped$restriction$A_Delta[-seq_len(n), , drop = FALSE], rows[, colnames(sd$A_Delta)])
  expect_identical(unname(shaped$restriction$d_vec), c(rep(0.1, n), numeric(nrow(rows))))
  expect_identical(names(shaped$restriction$d_vec), rownames(shaped$restriction$A_Delta))
  # The balanced window reaches the pure pre steps through the representation.
  built$representation$restriction_window <- -2L
  windowed <- engine$v3_attach_shape(built, list(shape = "monotone", direction = "decreasing"), full_path = TRUE)
  expect_identical(nrow(windowed$restriction$A_Delta), n + nrow(rows) - 1L)
})

test_that("the balanced settings decide which post periods the extra rows reach", {
  fit <- cohort_fit(y ~ d, data = independent_panel(), index = c("id", "time"))
  window <- .hc_balanced_window(fit)
  expect_identical(window[["upper"]], 2L)
  ell <- .hc_targets(fit, "att", window)[[1L]]$target
  count <- function(spec, ...) {
    rep <- .hc_engine_representation(.hc_representation(fit, ell, ...))
    nrow(.hc_backend()$v3_shape_rows(rep$coordinate_info, spec))
  }
  for (spec in list(list(shape = "sign", direction = "positive"), list(shape = "monotone", direction = "increasing"))) {
    expect_identical(count(spec, "cohort", window, "full"), 4L + 2L)
    expect_identical(count(spec, "cohort", window, "window"), 2L + 2L)
    expect_identical(count(spec, "aggregate", window), 2L)
  }
})

test_that("SDRM benchmarks are the pure pre-period second differences", {
  engine <- .hc_backend()
  info <- two_path_info()
  plain <- engine$v3_benchmark_operator(info)
  expect_identical(plain, engine$v3_first_difference_operator(info))
  expect_identical(engine$v3_benchmark_operator(info, spec = list(base = "RM")), plain)
  operator <- engine$v3_benchmark_operator(info, spec = list(base = "SDRM"))
  expect_identical(operator$rows$row[operator$rows$component == "pre"], c("d2_g3_s0", "d2_g5_s-1", "d2_g5_s0"))
  expect_identical(operator$rows$row[operator$rows$component == "post"],
                   c("d2_g3_s1", "d2_g3_s2", "d2_g5_s1", "d2_g5_s2", "d2_g5_s3"))
  expect_equal(operator$D1["d2_g5_s-1", ],
               expected_row(stats::setNames(c(1, -2, 1), vapply(-3:-1, cell, "", g = 5L))))
  expect_equal(operator$D1["d2_g3_s1", ],
               expected_row(stats::setNames(c(1, -2, 1), vapply(-1:1, cell, "", g = 3L))))
  window <- engine$v3_benchmark_operator(info, pre_window = -2L, spec = list(base = "SDRM"))
  expect_identical(window$rows$row[window$rows$component == "pre"], c("d2_g3_s0", "d2_g5_s0"))
  # Pre counts 3 and 4: two and three first differences, one and two second differences.
  expect_equal(nrow(engine$v3_rm_scenario_table(info, 1)$table), (2 * 2) * (2 * 3))
  expect_equal(nrow(engine$v3_rm_scenario_table(info, 1, spec = list(base = "SDRM"))$table), (2 * 1) * (2 * 2))
  expect_equal(nrow(engine$v3_rm_scenario_table(info, 0, spec = list(base = "SDRM"))$table), 1L)
})

test_that("an SDRM component bounds post second differences by one signed benchmark", {
  engine <- .hc_backend()
  info <- two_path_info()
  spec <- list(base = "SDRM", shape = "none")
  scenarios <- engine$v3_rm_scenario_table(info, 0.5, spec = spec)
  pick <- which(scenarios$table$g3 == "d2_g3_s0@@1" & scenarios$table$g5 == "d2_g5_s-1@@-1")
  expect_length(pick, 1L)
  restriction <- engine$v3_rm_component_restriction(info, 0.5, scenarios$table[pick, , drop = FALSE],
                                                    scenarios$operator, spec = spec)
  D2 <- scenarios$operator$D1
  A <- restriction$A_Delta
  expect_equal(nrow(A), 2L * 5L)
  expect_equal(A["d2_g3_s2_upper_bm_d2_g3_s0", ], D2["d2_g3_s2", ] - 0.5 * D2["d2_g3_s0", ])
  expect_equal(A["d2_g3_s2_lower_bm_d2_g3_s0", ], -D2["d2_g3_s2", ] - 0.5 * D2["d2_g3_s0", ])
  expect_equal(A[grep("^d2_g5_s3_upper", rownames(A)), ], D2["d2_g5_s3", ] + 0.5 * D2["d2_g5_s-1", ])
  expect_true(all(restriction$d_vec == 0))
  expect_identical(names(restriction$d_vec), rownames(A))
})

test_that("union components add the shape rows and drop exact repeats only", {
  engine <- .hc_backend()
  info <- two_path_info()
  component <- function(Mbar, shape, direction = NULL) {
    spec <- list(base = "RM", shape = shape, direction = direction)
    scenarios <- engine$v3_rm_scenario_table(info, Mbar, spec = spec)
    engine$v3_rm_component_restriction(info, Mbar, scenarios$table[1L, , drop = FALSE], scenarios$operator, spec = spec)
  }
  plain <- component(0, "none")
  expect_equal(nrow(plain$A_Delta), 2L * 5L)
  for (direction in c("increasing", "decreasing")) {
    monotone <- component(0, "monotone", direction)
    expect_identical(row_text(monotone$A_Delta), row_text(plain$A_Delta))
    expect_true(all(monotone$d_vec == 0))
  }
  # At zero the sign row at period 1 repeats a first-difference row; the later periods add rows.
  sign <- component(0, "sign", "positive")
  expect_equal(nrow(sign$A_Delta), 2L * 5L + 3L)
  expect_false(any(c(paste0("sign_", cell(3L, 1L)), paste0("sign_", cell(5L, 1L))) %in% rownames(sign$A_Delta)))
  expect_identical(names(sign$d_vec), rownames(sign$A_Delta))
  expect_false(anyDuplicated(sign$A_Delta) > 0L)
  # A positive bound moves the benchmark into every base row, so nothing repeats.
  expect_equal(nrow(component(0.5, "monotone", "increasing")$A_Delta), 2L * 5L + 5L)
  expect_equal(nrow(component(0.5, "sign", "negative")$A_Delta), 2L * 5L + 5L)
})

test_that("the union plug-in restriction adds the shape rows with zero bounds", {
  engine <- .hc_backend()
  info <- two_path_info()
  beta <- stats::setNames(seq_along(two_path_names)^2 / 100, two_path_names)
  plain <- engine$v3_rm_plugin_restriction(info, beta, 0.5)
  spec <- list(base = "RM", shape = "sign", direction = "negative")
  shaped <- engine$v3_rm_plugin_restriction(info, beta, 0.5, spec = spec)
  n <- nrow(plain$A_Delta)
  expect_identical(nrow(shaped$A_Delta), n + 5L)
  expect_identical(shaped$d_vec[seq_len(n)], plain$d_vec)
  expect_true(all(shaped$d_vec[-seq_len(n)] == 0))
  expect_identical(names(shaped$d_vec), rownames(shaped$A_Delta))
  sdrm <- engine$v3_rm_plugin_restriction(info, beta, 0.5, spec = list(base = "SDRM", shape = "none"))
  D2 <- engine$v3_second_difference_operator(info)$D2
  bound <- function(rows) 0.5 * max(abs(D2[rows, , drop = FALSE] %*% beta))
  expect_equal(unname(sdrm$d_vec), c(rep(bound("d2_g3_s0"), 2L * 2L),
                                     rep(bound(c("d2_g5_s-1", "d2_g5_s0")), 2L * 3L)))
  expect_equal(unname(sdrm$A_Delta[1L, ]), unname(D2["d2_g3_s1", ]))
})

test_that("component counts follow each base and the balanced window", {
  fit <- cohort_fit(y ~ d, data = independent_panel(), index = c("id", "time"))
  count_message <- function(restriction, direction = NULL, ...) {
    x <- suppressWarnings(cohort_sensitivity(fit, restriction, M = 0.5, direction = direction, seed = 1,
                                             control = list(max.components = 1L), ...))
    expect_identical(x$intervals$status, "inference_error")
    x$intervals$message
  }
  required <- function(name, n) paste0(name, " requires ", n, " signed benchmark components; increase max.components deliberately.")
  expect_identical(count_message("RM"), required("RM", 32))
  expect_identical(count_message("RMM", "increasing"), required("RMM", 32))
  expect_identical(count_message("SDRM"), required("SDRM", 12))
  expect_identical(count_message("SDRMB", "negative"), required("SDRMB", 12))
  expect_identical(count_message("RM", balanced = TRUE, cohort.paths = "window"), required("RM", 16))
  expect_identical(count_message("SDRM", balanced = TRUE, cohort.paths = "window"), required("SDRM", 4))
  expect_identical(count_message("SDRM", balanced = TRUE), required("SDRM", 12))
  zero <- cohort_sensitivity(fit, "SDRM", M = 0, seed = 1, control = c(quick_control, list(max.components = 1L)))
  expect_equal(zero$results[[1L]]$diagnostics$signed.components, 1L)
  expect_true(all(zero$intervals$success))
})

test_that("the SDRM family needs three pre-period coefficients, the others two", {
  fit <- cohort_fit(y ~ d, data = independent_short_panel(), index = c("id", "time"))
  expect_equal(sum(fit$coordinate_info$type == "pre"), 2L)
  for (restriction in c("SDRM", "SDRMB", "SDRMM")) {
    direction <- switch(restriction, SDRMB = "positive", SDRMM = "increasing")
    expect_warning(x <- cohort_sensitivity(fit, restriction, M = 0.5, direction = direction, seed = 1), "failed")
    expect_identical(x$intervals$status, "insufficient_prehistory")
    expect_false(x$intervals$success)
    expect_identical(x$intervals$message, paste0(restriction, " requires at least three pre-treatment periods, ",
                                                 "counting period 0, for every included cohort/path."))
  }
  x <- cohort_sensitivity(fit, "RMB", M = 0.5, direction = "negative", seed = 1, control = quick_control)
  expect_true(all(x$intervals$success))
})

test_that("settings keep the 1.0.0 names, and direction comes after control", {
  fit <- one_path_fit()
  plain <- c("restriction", "method", "full.path", "target", "framework", "M", "conf.level",
             "parallel", "cores", "seed", "task.seeds", "control")
  sd <- cohort_sensitivity(fit, "SD", M = 0, seed = 1, control = quick_control)
  rm <- cohort_sensitivity(fit, "RM", M = 0, seed = 1, control = quick_control)
  sdrm <- cohort_sensitivity(fit, "SDRM", M = 0, seed = 1, control = quick_control)
  sdb <- cohort_sensitivity(fit, "SDB", M = 0, direction = "negative", seed = 1, control = quick_control)
  rmm <- cohort_sensitivity(fit, "RMM", M = 0, direction = "decreasing", seed = 1, control = quick_control)
  for (x in list(sd, rm, sdrm)) {
    expect_identical(names(x$settings), plain)
    expect_null(x$results[[1L]]$diagnostics$direction)
  }
  for (x in list(sdb, rmm)) expect_identical(names(x$settings), c(plain, "direction"))
  expect_identical(sdb$settings$direction, "negative")
  expect_identical(rmm$settings$direction, "decreasing")
  expect_identical(sdb$results[[1L]]$diagnostics$direction, "negative")
  expect_identical(rmm$results[[1L]]$diagnostics$restriction, "RMM")
  expect_identical(sd$settings$full.path, FALSE)
  expect_identical(sdb$settings$full.path, FALSE)
  expect_null(rm$settings$full.path)
  expect_null(sdrm$settings$full.path)
  expect_null(rmm$settings$full.path)
  expect_identical(sdb$settings$control, quick_control)
  expect_identical(rmm$results[[1L]]$diagnostics$full.path, NA)
  panel <- cohort_fit(y ~ d, data = independent_panel(), index = c("id", "time"))
  balanced <- cohort_sensitivity(panel, "SDM", M = 0.01, direction = "increasing", balanced = TRUE,
                                 cohort.paths = "window", seed = 1, control = quick_control)
  expect_identical(names(balanced$settings), c(plain, "direction", "balanced", "cohort.paths", "window"))
})

test_that("empty and failed searches keep their statuses", {
  # At M = 0 the pre path falls to period 0, so SDRMB positive has an empty plug-in set.
  fit <- one_path_fit()
  clf <- cohort_sensitivity(fit, "SDRMB", M = 0, direction = "positive", seed = 1, control = quick_control)
  conditional <- cohort_sensitivity(fit, "SDRMB", M = 0, direction = "positive", method = "Conditional",
                                    seed = 1, control = quick_control)
  for (x in list(clf, conditional)) {
    expect_true(all(x$intervals$success))
    expect_true(all(is.na(c(x$intervals$plugin.lower, x$intervals$plugin.upper, x$intervals$center))))
    expect_true(all(is.finite(c(x$intervals$lower, x$intervals$upper))))
    expect_true(x$results[[1L]]$diagnostics$plugin.empty)
  }
  # The base plug-in set takes over for the search domain.
  expect_true(is.finite(conditional$results[[1L]]$diagnostics$search.center))
  expect_length(conditional$results[[1L]]$diagnostics$initial.domain, 2L)
  expect_s3_class(plot(clf), "ggplot")

  violated <- violated_fit()
  for (restriction in c("SDB", "SDRMB")) {
    empty <- cohort_sensitivity(violated, restriction, M = 0, direction = "positive", seed = 1, control = quick_control)
    expect_identical(empty$intervals$status, "empty")
    expect_true(empty$intervals$success)
    expect_true(is.na(empty$intervals$lower) && is.na(empty$intervals$upper))
    expect_warning(open <- cohort_sensitivity(violated, restriction, M = 0, direction = "positive", method = "Conditional",
      seed = 1, control = list(grid.points = 21L, max.refinements = 0L, max.expansions = 2L)), "failed")
    expect_identical(open$intervals$status, "uncertified_empty_search")
    expect_false(open$intervals$success)
  }
})

