test_that("the Conditional mesh audit runs for the shaped restrictions only on request", {
  fit <- one_path_fit()
  ctl <- list(lf.sims = 64L, grid.points = 21L)
  run <- function(restriction, method, control, direction = NULL) {
    cohort_sensitivity(fit, restriction, M = 0.01, method = method, direction = direction, seed = 1, control = control)
  }
  audited <- function(x) x$results[[1L]]$diagnostics$resolution.stable
  expect_true(is.na(audited(run("SDB", "Conditional", ctl, "positive"))))
  expect_true(is.na(audited(run("SDM", "Conditional", ctl, "increasing"))))
  expect_false(is.na(audited(run("SD", "Conditional", ctl))))
  # Either value set by the user wins, and settings keep what the user passed.
  on <- run("SDB", "Conditional", c(ctl, list(topology.audit = TRUE)), "positive")
  expect_false(is.na(audited(on)))
  expect_identical(on$settings$control$topology.audit, TRUE)
  off <- run("SD", "Conditional", c(ctl, list(topology.audit = FALSE)))
  expect_true(is.na(audited(off)))
  # C-LF keeps its audit.
  expect_false(is.na(audited(run("SDB", "C-LF", ctl, "positive"))))
  default <- run("SDB", "Conditional", ctl, "positive")
  expect_false("topology.audit" %in% names(default$settings$control))
})

test_that("SDRM searches around the linear continuation, as SD does", {
  fit <- one_path_fit()
  # The center is set before the search, and max.expansions = 0 stops there.
  center <- function(restriction) {
    x <- suppressWarnings(cohort_sensitivity(fit, restriction, M = 0.5, method = "Conditional", seed = 1,
                                             control = list(grid.points = 21L, max.expansions = 0L)))
    expect_identical(x$intervals$status, "domain_stability_limit")
    x$results[[1L]]$diagnostics$search.center
  }
  post <- c(1, 2, 3)
  linear <- mean(c(0.055, 0.075, 0.064) - (0 + post * (0 - 0.0100)))
  constant <- mean(c(0.055, 0.075, 0.064))
  expect_equal(center("SD"), linear, tolerance = 1e-12)
  expect_equal(center("SDRM"), linear, tolerance = 1e-12)
  expect_equal(center("RM"), constant, tolerance = 1e-12)
})

test_that("print and plot name the restriction and direction", {
  labelled <- function(restriction, direction = NULL, full.path = NULL, framework = "cohort", method = "c_lf") {
    settings <- list(restriction = restriction, method = method, full.path = full.path, target = "att",
                     framework = framework, M = 1, conf.level = 0.95)
    settings$direction <- direction
    structure(list(settings = settings, estimates = data.frame(estimate = 0),
      fit = list(data_info = list(balanced = TRUE)), results = list(list(diagnostics = list())),
      intervals = data.frame(target = "att", label = "ATT", cohort = NA_integer_, relative_period = NA_integer_,
        M = 1, component = 1L, lower = -0.4, upper = 0.6, center = 0.1, plugin.lower = -0.3, plugin.upper = -0.1,
        success = TRUE, status = "ok", message = "")), class = "cohort_sensitivity")
  }
  header <- function(x) utils::capture.output(print(x))[1L]
  expect_identical(header(labelled("SD", full.path = FALSE)), "cohort inference | SD | C-LF | post-only")
  expect_identical(header(labelled("SDB", "positive", FALSE)), "cohort inference | SDB, positive | C-LF | post-only")
  expect_identical(header(labelled("SDM", "increasing", TRUE, method = "conditional")),
                   "cohort inference | SDM, increasing | Conditional | full path")
  expect_identical(header(labelled("RM")), "cohort inference | RM | C-LF | cohort-specific pre-period benchmarks")
  expect_identical(header(labelled("RMB", "negative", framework = "aggregate")),
                   "aggregate inference | RMB, negative | C-LF | aggregate pre-period benchmark")
  expect_identical(header(labelled("SDRM")),
                   "cohort inference | SDRM | C-LF | cohort-specific pre-period second-difference benchmarks")
  expect_identical(header(labelled("SDRMM", "decreasing", framework = "aggregate", method = "conditional")),
                   "aggregate inference | SDRMM, decreasing | Conditional | aggregate pre-period second-difference benchmark")
  caption <- function(x) gsub("\n", " ", plot(x)$labels$caption, fixed = TRUE)
  expect_match(caption(labelled("SD", full.path = FALSE)), "C-LF; SD, post-only; cohort", fixed = TRUE)
  expect_match(caption(labelled("SDB", "positive", FALSE)), "C-LF; SDB, positive, post-only; cohort", fixed = TRUE)
  expect_match(caption(labelled("SDM", "decreasing", TRUE)), "C-LF; SDM, decreasing, full path; cohort", fixed = TRUE)
  expect_match(caption(labelled("RM")), "C-LF; RM; cohort", fixed = TRUE)
  expect_match(caption(labelled("RMB", "negative")), "C-LF; RMB, negative; cohort", fixed = TRUE)
  expect_match(caption(labelled("SDRM")), "C-LF; SDRM; cohort", fixed = TRUE)
  expect_match(caption(labelled("SDRMM", "increasing")), "C-LF; SDRMM, increasing; cohort", fixed = TRUE)
  expect_identical(plot(labelled("SDB", "positive", FALSE))$labels$x, "M")
  expect_identical(plot(labelled("SDM", "decreasing", TRUE))$labels$x, "M")
  for (name in c("RM", "SDRM")) expect_true(is.expression(plot(labelled(name))$labels$x))
  expect_true(is.expression(plot(labelled("SDRMM", "increasing"))$labels$x))
})

