test_that("imputation and CS-NYT agree on a balanced panel under sign, monotonicity, and SDRM", {
  d <- independent_panel()
  imp <- cohort_fit(y ~ d, data = d, index = c("id", "time"), estimator = "imp")
  nyt <- cohort_fit(y ~ d, data = d, index = c("id", "time"), estimator = "cs_nyt")
  cases <- list(list("SDB", "positive", 0.01), list("SDB", "negative", 0.01), list("SDM", "increasing", 0.01),
                list("SDRM", NULL, 0.5), list("SDRMM", "decreasing", 0.5))
  for (case in cases) {
    a <- cohort_sensitivity(imp, case[[1L]], M = case[[3L]], direction = case[[2L]], seed = 3,
                            control = c(quick_control, list(endpoint.tol = 1e-7)))
    b <- cohort_sensitivity(nyt, case[[1L]], M = case[[3L]], direction = case[[2L]], seed = 3,
                            control = c(quick_control, list(endpoint.tol = 1e-7)))
    expect_identical(a$intervals$status, b$intervals$status, info = case[[1L]])
    expect_equal(ordered_endpoints(a), ordered_endpoints(b), tolerance = 1e-6, info = case[[1L]])
    expect_equal(a$intervals$plugin.lower, b$intervals$plugin.lower, tolerance = 1e-9, info = case[[1L]])
    expect_equal(a$intervals$plugin.upper, b$intervals$plugin.upper, tolerance = 1e-9, info = case[[1L]])
  }
})

test_that("the nested FLCI solver runs on the installed CVXR and matches the direct solver", {
  skip_if_not_installed("CVXR")
  skip_if_not("ECOS" %in% CVXR::installed_solvers())
  fit <- cohort_fit(y ~ d, data = independent_short_panel(), index = c("id", "time"))
  direct <- cohort_sensitivity(fit, M = c(0, 0.01), method = "FLCI", seed = 3)
  nested <- cohort_sensitivity(fit, M = c(0, 0.01), method = "FLCI", seed = 3,
                               control = list(flci.solver = "nested"))
  expect_identical(nested$intervals$status, c("ok", "ok"))
  expect_equal(ordered_endpoints(nested), ordered_endpoints(direct), tolerance = 1e-6)
  x <- CVXR::Variable(2L)
  problem <- CVXR::Problem(CVXR::Minimize(sum(x)), list(x >= c(1, 2)))
  solution <- .hc_backend()$flci_cvxr_run(problem, list(solver = "ECOS"))
  expect_identical(tolower(as.character(solution$status)), "optimal")
  expect_equal(as.numeric(solution$value), 3, tolerance = 1e-6)
  expect_equal(as.numeric(solution$getValue(x)), c(1, 2), tolerance = 1e-6)
})

test_that("the nine restrictions reproduce CRAN HonestDiD on one path", {
  fit <- one_path_fit()
  h <- 0.0005
  slack <- 1e-6
  for (i in seq_len(nrow(honestdid_refs))) {
    ref <- honestdid_refs[i, ]
    case <- paste(ref$restriction, ref$direction, ref$method)
    x <- cohort_sensitivity(fit, ref$restriction, M = ref$M, target = "att", method = ref$method, seed = 1,
                            direction = if (is.na(ref$direction)) NULL else ref$direction,
                            control = list(grid.points = 31L, topology.audit = FALSE, lf.sims = 1000L))
    expect_true(all(x$intervals$status %in% c("ok", "disconnected")), info = case)
    lower <- min(x$intervals$lower)
    upper <- max(x$intervals$upper)
    if (ref$method == "Conditional") {
      # A reference endpoint is a grid point inside the set; the package bisects to the true endpoint.
      expect_true(lower >= ref$lower - h - slack && lower <= ref$lower + slack, info = case)
      expect_true(upper >= ref$upper - slack && upper <= ref$upper + h + slack, info = case)
    } else {
      # The allowance covers the two simulated critical values, HonestDiD's and the package's.
      allowance <- if (ref$restriction %in% c("SD", "SDB", "SDM")) 0.003 else 0.012
      expect_lte(abs(lower - ref$lower), allowance, label = paste(case, "lower gap"))
      expect_lte(abs(upper - ref$upper), allowance, label = paste(case, "upper gap"))
    }
  }
})
